\setmainfont[Scale=1]{Times New Roman}
\setsansfont[Scale=1]{Arial}
\setmonofont[Scale=1]{Courier New}
% Inkwell heading typography
\newfontfamily\inkwellheadingfont{Arial}[Scale=1]
\definecolor{inkwellheadingcolor}{HTML}{336699}
\titleformat{\section}{\normalfont\inkwellheadingfont\fontsize{17.28pt}{20.736pt}\selectfont\mdseries\color{inkwellheadingcolor}}{\thesection}{1em}{}
\titleformat{\subsection}{\normalfont\inkwellheadingfont\fontsize{14.4pt}{17.28pt}\selectfont\mdseries\color{inkwellheadingcolor}}{\thesubsection}{1em}{}
\titleformat{\subsubsection}{\normalfont\inkwellheadingfont\fontsize{12pt}{14.4pt}\selectfont\mdseries\color{inkwellheadingcolor}}{\thesubsubsection}{1em}{}
\titleformat{\paragraph}[runin]{\normalfont\inkwellheadingfont\fontsize{12pt}{14.4pt}\selectfont\mdseries\color{inkwellheadingcolor}}{\theparagraph}{1em}{}
\titleformat{\subparagraph}[runin]{\normalfont\inkwellheadingfont\fontsize{12pt}{14.4pt}\selectfont\mdseries\color{inkwellheadingcolor}}{\thesubparagraph}{1em}{}
% Inkwell highlighted and plain code sizing
\usepackage{fvextra}
\newcommand{\inkwellcodesize}{\fontsize{8pt}{9.6pt}\selectfont}
\DefineVerbatimEnvironment{Highlighting}{Verbatim}{commandchars=\\\{\},breaklines,breakanywhere,fontsize=\inkwellcodesize}
\DefineVerbatimEnvironment{verbatim}{Verbatim}{breaklines,breakanywhere,fontsize=\inkwellcodesize}
% Inkwell figure and body-table caption sizing
\DeclareCaptionFont{inkwellcaption}{\fontsize{9pt}{10.8pt}\selectfont}
\captionsetup[figure]{font=inkwellcaption}
\captionsetup[table]{font=inkwellcaption}
% Used only by body-typography.lua around Pandoc Table nodes
\newcommand{\inkwellbodytablesize}{\fontsize{10pt}{12pt}\selectfont}

